"""Build one Automation & Architecture batch; acceptance is a separate gate."""
import json,runpy,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1]
SRC={
'python':('Python 3.12 tutorial and standard library','https://docs.python.org/3.12/tutorial/'),
'ip':('Python 3.12 ipaddress','https://docs.python.org/3.12/library/ipaddress.html'),
'yaml':('YAML 1.2.2 specification','https://yaml.org/spec/1.2.2/'),
'http':('RFC 9110 HTTP semantics','https://www.rfc-editor.org/rfc/rfc9110.html'),
'ssh':('RFC 4253 SSH transport','https://www.rfc-editor.org/rfc/rfc4253.html'),
'snmp':('RFC 3414 SNMPv3 USM','https://www.rfc-editor.org/rfc/rfc3414.html'),
'netconf':('RFC 6241 NETCONF','https://www.rfc-editor.org/rfc/rfc6241.html'),
'restconf':('RFC 8040 RESTCONF','https://www.rfc-editor.org/rfc/rfc8040.html'),
'yang':('RFC 7950 YANG 1.1','https://www.rfc-editor.org/rfc/rfc7950.html'),
'cisco':('Cisco IOS XE 17 release-specific configuration guides','https://www.cisco.com/c/en/us/support/ios-nx-os-software/ios-xe-17/products-installation-and-configuration-guides-list.html'),
'netmiko':('Netmiko project documentation','https://ktbyers.github.io/netmiko/'),
'paramiko':('Paramiko SSHClient contract','https://docs.paramiko.org/en/stable/api/client.html'),
'napalm':('NAPALM NetworkDriver contract; verify installed driver support','https://napalm.readthedocs.io/en/latest/base.html'),
'requests':('Requests client behavior','https://requests.readthedocs.io/en/latest/user/quickstart/'),
'ansible':('Ansible network automation guide','https://docs.ansible.com/projects/ansible/latest/network/getting_started/index.html'),
'ciscoans':('cisco.ios interfaces resource module; reviewed collection 11.5.1 page','https://docs.ansible.com/projects/ansible/latest/collections/cisco/ios/ios_interfaces_module.html'),
'jinja':('Jinja 3.1 API and StrictUndefined','https://jinja.palletsprojects.com/en/stable/api/'),
'git':('Pro Git 2nd edition','https://git-scm.com/book/en/v2'),
'github':('GitHub Actions secure use','https://docs.github.com/en/actions/reference/security/secure-use'),
'gitlab':('GitLab protected environments','https://docs.gitlab.com/ci/environments/protected_environments/'),
'terraform':('Terraform workflow and providers','https://developer.hashicorp.com/terraform/intro'),
'tfstate':('Terraform state and operational mapping','https://developer.hashicorp.com/terraform/language/state'),
'netbox':('NetBox documentation and intended role','https://netboxlabs.com/docs/netbox/'),
'sre':('Google SRE monitoring distributed systems','https://sre.google/sre-book/monitoring-distributed-systems/'),
'nist':('NIST SP 800-34 Rev 1 contingency planning','https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final'),
'otel':('OpenTelemetry signal concepts','https://opentelemetry.io/docs/concepts/signals/'),
'planes':('Cisco IOS XE hardening: management, control and data planes','https://sec.cloudapps.cisco.com/security/center/resources/IOS_XE_hardening')}
SCOPES={
'change':'Four declared gates (valid input, approved revision, current baseline, recovery ready) permit a simulated change. The result is a checklist predicate, not authentication, a distributed lock, or proof that an external action is safe.',
'budget':'A bounded work estimate: target count multiplied by maximum attempts gives calls; dividing by supplied calls/second gives an ideal lower-bound duration. It omits latency, backoff, concurrency overhead and server behavior. No requests are sent.',
'capacity':'Homogeneous survivor-capacity envelope: (nodes minus failed nodes) times (capacity minus reserve) compared with aggregate demand in common abstract units. It does not model placement, quorum, replication or latency.',
'recovery':'Serial recovery budget: detection plus decision plus restoration plus validation compared with RTO, and supplied recoverable-point age compared with RPO. Durations are minutes. No actual recovery timing or data loss is measured.',
'policy':'A declared source-role, destination-role and service relation with explicit allowed flows and default deny. It does not implement a firewall, TCP state, routing, identity verification or packet forwarding.'}
def build(batch):
 m=json.loads((R/'content/enrichment.json').read_text(encoding='utf-8')); b=next(x for x in m['batches'] if x['id']==batch)
 assert batch in ('22','23','24')
 for dep in b['dependencies']:assert next(x for x in m['batches'] if x['id']==dep)['status']=='completed','Accept the prior batch first'
 inv=json.loads((R/'content/roadmap-inventory.json').read_text(encoding='utf-8'));names={x['id']:x['name'] for x in inv['nodes']};order=list(names)
 specs=[s for s in runpy.run_path(str(R/'tools/automation-authoring.py'))['S'] if s['id'] in b['nodeIds']];assert {s['id'] for s in specs}==set(b['nodeIds'])
 lessons=[]; workbook=['# Automation & Infrastructure Architecture — Batch '+batch,'','The incident statements are authored teaching cases. The inspector reads these cases; it does not execute vendor operations. Python 3.10+ runs the separate local architecture lab with only standard-library dependencies. External packages and device procedures require a separately pinned, supported disposable environment.','','## Evidence procedure','','1. Identify the intended operation, authoritative input and observer.','2. Predict a baseline result and a discriminating fault observation.','3. Compare the authored case with the model scope; do not label either as captured device evidence.','4. Record the narrow repair, positive postcondition, negative test and rollback.','5. Run the local lab where relevant and preserve its actual JSON evidence separately.','']
 for s in specs:
  id=s['id']; title=names[id];t=s['terms'];ms=s['mechanism'];scope=SCOPES[s['kind']]
  qs=s['questions']+[
   ['Identify the first failed boundary in this '+title+' case.',s['fault'],'Use the supplied observation to choose a testable hypothesis rather than repeating an entire deployment.'],
   ['What evidence closes the '+title+' incident?',s['repair'],'Verify the original intended operation and an excluded operation; retain the result and its observer.'],
   ['Contrast '+t[0][0]+' with '+t[1][0]+'.',t[0][1]+'. '+t[1][1]+'.',t[0][2]+'. '+t[1][2]+'.'],
   ['Why does '+t[2][0]+' not establish the entire outcome?',t[2][2]+'.',ms[2]],
   ['What evidence should be retained before changing this case?',s['case']+' Record the exact input revision, observed baseline, target identity and tested recovery path.','A reproducible change requires a concrete starting state and an identified artifact, not only a narrative description.'],
   ['What does the companion '+s['kind']+' model leave unverified?',scope,'Supplied-input calculations and declared gates cannot establish external execution or measured service behavior.']]
  quick=[['State the purpose of '+title+'.',s['definition'],ms[0]],['What is the second handoff in this mechanism?',ms[1],t[1][2]+'.'],['Which observation would you require after recovery?',s['repair'],ms[2]]]
  def q(row,i,prefix):return dict(questionId=f'{id}-{prefix}{i+1}',topicId=id,difficulty='foundational' if i<2 else 'intermediate' if i<6 else 'advanced',type='short-answer',question=row[0],answer=row[1],explanation=row[2],testedConcept=t[i%3][0] if i<4 else ['Fault localization','Recovery evidence','Concept comparison','Boundary limit','Change provenance','Model scope'][i-4])
  command='python labs/automation-lab.py --run' if id=='lab-9' else 'python labs/automation-evidence.py --topic '+id
  l=dict(id=id,batch=batch,title=title,subtitle=s['case'],level='Foundation → Controlled operations',minutes=100 if id=='lab-9' else 45,interactive='aa-'+id,
   definition=s['definition'],purpose='Apply this concept to a bounded infrastructure operation whose result another operator can reproduce. '+s['case']+' The outcome is correct state with preserved access boundaries and recoverability, not merely a completed script.',
   mental='Follow the handoff between '+', '.join(x[0] for x in t)+'. '+ms[0]+' Then ask which evidence is produced at each boundary and who is responsible for interpreting it. '+t[0][2]+'. '+t[1][2]+'. '+t[2][2]+'. A helpful analogy is a reviewed work order: the order describes intent, the executor performs an action, and a separate inspection checks the result. None of these stages can substitute for the others.',
   components=[x[0]+': '+x[1]+'. '+x[2]+'.' for x in t],mechanism=ms,flow=[['Operation and scope',s['case']]]+[[x[0],step] for x,step in zip(t,ms)],comparison=t,
   example='Worked incident: '+s['case']+' Failure: '+s['fault']+' Recovery: '+s['repair']+' The key distinction is illustrated by this question: '+qs[0][0]+' '+qs[0][1]+' '+qs[0][2]+' Record which values are supplied assumptions and which would need observation on a real target.',
   commands=[dict(filename='offline-evidence.txt',platform='Python 3.10+ standard library; run from course root',code=command,explanation='The topic inspector reads authored cases without network calls or writes. The integrated lab instead executes validation, deterministic rendering and guarded file changes inside a fresh owned temporary directory.',expected='Topic inspector: JSON marked AUTHORED, with the topic identity, mechanism and incident. Integrated lab: PASS with actual local-file evidence, idempotent second apply, stale-write rejection, byte restoration and cleanup.')],
   configuration='Identify the authoritative input and the affected resource before proposing a change. '+ms[0]+' '+ms[1]+' Preserve a baseline and review the smallest concrete diff. In this case the failure is: '+s['fault']+' Do not deploy a guessed platform command from a conceptual description. Pin external library and platform versions, use the linked exact contract and test the operation in an owned disposable environment. '+s['repair'],
   production='Define an owner, change scope, acceptance test and recovery budget. '+ms[2]+' Retain per-target outcomes and distinguish failed, unreachable, rejected and unknown-completion states. Stage changes through a canary and stop expansion when the observed result differs from the plan. Record the input revision and rendered artifact identity so a later operator can determine exactly what was attempted. Parallel execution does not remove dependency ordering or partial failure.',
   security='Restrict automation identities to required actions and verify the peer before sending credentials. '+t[0][2]+'. '+t[2][2]+'. Keep secrets out of inventories, examples, diffs and evidence logs; store only references or sanitized metadata. Test an intentionally denied action as well as the intended positive action. A recovery that broadens access beyond the approved policy is not accepted. Review untrusted data before it reaches a template, shell or privileged deployment runner.',
   performance='Measure the relevant operation and its time window instead of assuming faster execution is better. '+ms[1]+' Bound concurrency, retries and resource consumption; separate queueing, processing and dependency delays where observable. Tail latency and missing data may matter more than a healthy average. This lesson’s separate companion has a deliberately narrower scope: '+scope,
   troubleshooting=[[s['fault'],s['repair']],[qs[1][0],qs[1][1]+' '+qs[1][2]],[qs[2][0],qs[2][1]+' '+qs[2][2]],['A tool reports success but the service does not meet intent','Check target identity, revision and postcondition first. A successful transport, render or process exit is evidence only for that stage. Preserve unknown completion rather than retrying a possibly applied write blindly.']],mistakes=[x[2] for x in s['questions']]+[t[0][2]+'.',t[2][2]+'.'],
   ports='Transport depends on the selected operation: HTTPS commonly uses TCP 443, SSH TCP 22, NETCONF over SSH has assigned TCP 830, and ordinary SNMP polling uses UDP 161 with notifications commonly on UDP 162. These are protocol conventions, not a blanket firewall policy. Local parsing, Git object inspection and the offline lab need no device connection. Verify the actual listener, transport, management scope and return path before permitting traffic.',
   prerequisites=[order[order.index(id)-1]],related=[order[order.index(id)+1]],
   lab=dict(objective='Diagnose and recover the stated '+title+' failure with an explicit evidence boundary. '+s['case'],requirements='Browser and notes for the authored worksheet; Python 3.10+ for the inspector and integrated local lab. External tool or vendor execution is optional guided work requiring a separately supported owned target, pinned dependencies and a captured baseline.',topology=[x[0]+' → '+x[1] for x in t],steps=['Read the case and identify intent, owner, observer and target scope. '+s['case'],'Write a prediction before revealing the baseline explanation. '+ms[0],'Select Fault and locate the first broken handoff. '+s['fault'],'Propose one observation that could disprove your diagnosis. '+qs[1][0],'Select Recovery and compare with the required result. '+s['repair'],'Change one input in the companion model and explain exactly what it computes. Reset it and retain its stated limitation.','Run the local evidence command and label the output authored; for lab-9 retain actual local execution evidence separately.','For an optional platform extension, use the cited installed-version contract, a canary and an independently tested recovery path. Record positive and negative postconditions; stop if identity, scope or partial state differs from the approved plan.'],verification=s['repair']+' Record baseline, fault and recovery separately with revision, observer and timestamp; do not infer remote execution from a browser control.',troubleshooting=s['fault']+' '+qs[3][1],challenge=qs[3][0]+' Add a concurrent actor or shared dependency and explain how acceptance changes.',cleanup='Reset browser inputs. The inspector performs no writes. The integrated local lab restores and removes only its own temporary directory, including intentional interruption. Optional platform work must restore the captured owned baseline and confirm service state before removing temporary artifacts.'),
   glossary={x[0]:x[1]+'. '+x[2]+'.' for x in t},sources=[dict(title=SRC[k][0],url=SRC[k][1],checked='2026-10-09') for k in s['refs']],quick=[q(x,i,'QC') for i,x in enumerate(quick)],exams=[q(x,i,'Q') for i,x in enumerate(qs)],automationArchitecture=dict(kind=s['kind'],baseline=s['case'],fault=s['fault'],restore=s['repair'],scope=scope),artifacts=[dict(title='Batch '+batch+' evidence workbook',path='labs/automation-'+batch+'-workbook.md'),dict(title='Read-only incident inspector',path='labs/automation-evidence.py')])
  snippets=runpy.run_path(str(R/'tools/automation-snippets.py'))['SNIPPETS']
  if id in snippets:l['commands'].append(dict(filename='example.py',platform='Python 3.10+ standard library; standalone local example',code=snippets[id],explanation='Save as example.py and run python example.py. This executes only local Python operations with synthetic input; the Files example owns and removes a temporary directory.',expected='Printed valid results and deliberate rejection or restoration evidence. No remote service is contacted.'))
  if id=='lab-9':
   l['artifacts'] += [dict(title='Executable local architecture rehearsal',path='labs/automation-lab.py'),dict(title='Enterprise architecture design and guided extension',path='labs/automation-architecture.md')]
   l['lab']['topology']=['Git revision → schema validation → deterministic render → reviewed plan → canary → verification','Site A: edge / management / application / data zones','Site B: edge / management / application / data zones','Shared dependencies: identity, DNS, time, observability, backup keys and operator access','Recovery path: independent management → restore data and configuration → validate client operation']
   l['lab']['steps']=['Read labs/automation-architecture.md and complete its original enterprise design deliverables.','Run python labs/automation-lab.py --run. It creates no server, VM or network device.','Inspect actual schema rejection, rendered hash, first change, second no-op and stale-write rejection.','Inspect the synthetic policy, survivor capacity and serial recovery budgets separately from actual file operations.','Run python labs/automation-lab.py --run --inject-failure applied. Expect INTERRUPTED, exit 2, restored true and cleaned true.','Repeat with validated, drifted and restored interruption phases. Each run owns a fresh temporary directory.','Use the guided extension to version intent in an owned repository and reproduce the design on a compatible disposable platform. Pin tools, retain diffs, validate allowed and denied flows and exercise recovery.','Submit the topology, policy and authority matrices, capacity/RTO/RPO assumptions, executable evidence, rollback runbook and a list of remote operations not executed.']
   l['lab']['verification']='Normal run returns PASS with changed true, secondChanged false, staleRejected true, restored true and cleaned true. Intentional interruptions return INTERRUPTED and exit 2 while still restoring and cleaning. The synthetic design budgets are calculations; real routing, HA, service recovery and platform deployment remain unexecuted.'
  lessons.append(l)
  workbook += ['## '+id+' — '+title,'',s['definition'],'','Baseline: '+s['case'],'','Fault: '+s['fault'],'','Acceptance: '+s['repair'],'','Mechanism:']+['- '+x for x in ms]+['','Companion limit: '+scope,'','Evidence command: `'+command+'`','']
 (R/f'content/batch-{batch}.js').write_text('window.INFRA_BATCHES = window.INFRA_BATCHES || {};\nwindow.INFRA_BATCHES['+json.dumps(batch)+'] = '+json.dumps(lessons,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
 (R/f'labs/automation-{batch}-workbook.md').write_text('\n'.join(workbook)+'\n',encoding='utf-8')
 if b['status']!='completed':b.update(status='in-progress',draftNodeIds=b['nodeIds'])
 b.update(visualizations='Four-step mechanism, concept comparison, incident rehearsal and one scoped companion model per topic.',labs='Read-only authored evidence inspector; integrated local validation/render/change/rollback lab and guided enterprise architecture extension.',interactions=f'{len(lessons)} incident panels; {10*len(lessons)} exams and {3*len(lessons)} quick checks.')
 m.update(currentBatch=batch,nextNode=b['nodeIds'][0]);(R/'content/enrichment.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Built',batch,len(lessons))
if __name__=='__main__':build(sys.argv[1])
